import { Product } from './Product';

export class Catalogue {
  private products: Map<string, Product> = new Map();
  private stock: Map<string, number> = new Map();
  private reserved: Map<string, number> = new Map();

  addProduct(id: string, product: Product, quantity: number): void {
    this.products.set(id, product);
    this.stock.set(id, quantity);
    this.reserved.set(id, 0);
  }

  getProduct(id: string): Product | undefined {
    return this.products.get(id);
  }

  getAllProducts(): Product[] {
    return Array.from(this.products.values());
  }

  getAvailableStock(productId: string): number {
    const total = this.stock.get(productId) ?? 0;
    const reserved = this.reserved.get(productId) ?? 0;
    return total - reserved;
  }

  getTotalStock(productId: string): number {
    return this.stock.get(productId) ?? 0;
  }

  getReservedStock(productId: string): number {
    return this.reserved.get(productId) ?? 0;
  }

  hasStock(productId: string, quantity: number): boolean {
    return this.getAvailableStock(productId) >= quantity;
  }

  reserve(productId: string, quantity: number): void {
    if (!this.hasStock(productId, quantity)) {
      throw new Error(`Insufficient stock for product ${productId}`);
    }
    const current = this.reserved.get(productId) ?? 0;
    this.reserved.set(productId, current + quantity);
  }

  releaseReservation(productId: string, quantity: number): void {
    const current = this.reserved.get(productId) ?? 0;
    this.reserved.set(productId, Math.max(0, current - quantity));
  }
}

