import { OrderItem } from './OrderItem';

export type OrderState = 'placed' | 'paid' | 'packed' | 'shipped' | 'delivered';

const STATE_TRANSITIONS: Record<OrderState, OrderState> = {
  placed: 'paid',
  paid: 'packed',
  packed: 'shipped',
  shipped: 'delivered',
  delivered: 'delivered',
};

export class Order {
  id: string;
  state: OrderState;
  items: OrderItem[];
  createdAt: Date;

  constructor(id: string, items: OrderItem[]) {
    this.id = id;
    this.items = items;
    this.state = 'placed';
    this.createdAt = new Date();
  }

  transitionTo(nextState: OrderState): void {
    if (this.state === 'shipped' && nextState === this.state) {
      throw new Error('Order already shipped, cannot transition');
    }
    if (STATE_TRANSITIONS[this.state] !== nextState) {
      throw new Error(`Cannot transition from ${this.state} to ${nextState}`);
    }
    this.state = nextState;
  }

  canBeCancelled(): boolean {
    return this.state !== 'shipped' && this.state !== 'delivered';
  }
}

